const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Extract text from docx ---
function readDocx(filename) {
  const buf = fs.readFileSync(filename);
  const target = 'word/document.xml';
  let pos = 0;
  while (pos < buf.length - 30) {
    if (buf[pos]===0x50 && buf[pos+1]===0x4b && buf[pos+2]===0x03 && buf[pos+3]===0x04) {
      const fnLen = buf.readUInt16LE(pos+26);
      const extraLen = buf.readUInt16LE(pos+28);
      const compressionMethod = buf.readUInt16LE(pos+8);
      const compressedSize = buf.readUInt32LE(pos+18);
      const fn = buf.toString('utf8', pos+30, pos+30+fnLen);
      const dataStart = pos+30+fnLen+extraLen;
      if (fn === target) {
        const compData = buf.slice(dataStart, dataStart+compressedSize);
        return compressionMethod === 8
          ? zlib.inflateRawSync(compData).toString('utf8')
          : compData.toString('utf8');
      }
      pos = dataStart + compressedSize;
    } else {
      pos++;
    }
  }
  return null;
}

const xml = readDocx('customer_report.docx');
const paragraphs = xml.split(/<\/w:p>/).map(p => {
  const texts = [];
  const regex = /<w:t[^>]*>([^<]*)<\/w:t>/g;
  let m;
  while ((m = regex.exec(p)) !== null) texts.push(m[1]);
  return texts.join('');
}).filter(t => t.length > 0);

// --- Build PDF ---
const doc = new PDFDocument({ size: 'A4', margins: { top: 50, bottom: 50, left: 50, right: 50 } });
const stream = fs.createWriteStream('customer_report.pdf');
doc.pipe(stream);

const pageWidth = doc.page.width - 100; // usable width

paragraphs.forEach((line, i) => {
  if (i === 0) {
    // Title
    doc.fontSize(20).font('Helvetica-Bold').text(line, { align: 'center' });
    doc.moveDown(1);
  } else if (/^(Maya Chen|Jordan Alvarez|Evan Parker|Nina Patel|Alicia Morgan|Sofia Ramirez)$/.test(line)) {
    // Customer name header
    doc.moveDown(0.5);
    doc.fontSize(14).font('Helvetica-Bold').fillColor('#1a5276').text(line);
    doc.moveTo(50, doc.y).lineTo(50 + pageWidth, doc.y).strokeColor('#1a5276').lineWidth(1).stroke();
    doc.moveDown(0.3);
  } else if (line.startsWith('Email:')) {
    // Customer details
    const parts = line.split(' | ');
    parts.forEach(part => {
      const [label, ...rest] = part.split(': ');
      const value = rest.join(': ');
      doc.fontSize(9).font('Helvetica-Bold').fillColor('#555555').text(label + ': ', { continued: true });
      doc.font('Helvetica').fillColor('#333333').text(value);
    });
    doc.moveDown(0.4);
  } else if (line.startsWith('Order ORD-')) {
    // Order line
    const orderMatch = line.match(/^Order (ORD-[A-F0-9]+) — ([\d-]+) \| Status: (\w+) \| Total: (\S+)$/);
    if (orderMatch) {
      const [, orderId, date, status, total] = orderMatch;
      const statusColor = status === 'cancelled' ? '#c0392b' : '#27ae60';
      doc.fontSize(10).font('Helvetica-Bold').fillColor('#2c3e50').text(orderId, { continued: true });
      doc.font('Helvetica').fillColor('#666666').text('  ' + date, { continued: true });
      doc.font('Helvetica-Bold').fillColor(statusColor).text('  ' + status, { continued: true });
      doc.font('Helvetica-Bold').fillColor('#2c3e50').text('  ' + total);
    } else {
      doc.fontSize(10).font('Helvetica').fillColor('#333333').text(line);
    }
  } else if (line.trim().startsWith('Items:')) {
    // Items line
    doc.fontSize(9).font('Helvetica').fillColor('#777777').text('    ' + line.trim());
    doc.moveDown(0.2);
  } else {
    doc.fontSize(10).font('Helvetica').fillColor('#333333').text(line);
  }
});

doc.end();
stream.on('finish', () => {
  const stats = fs.statSync('customer_report.pdf');
  console.log('PDF created: customer_report.pdf (' + (stats.size / 1024).toFixed(1) + ' KB)');
});
"

